#include <stdio.h>

int calculate(int value);       /* function declaration */
extern int shared_total;        /* declaration; defined below */
static int adjust(int value) {  /* internal linkage */
    return value + 1;
}

int shared_total = 40;          /* external definition */

int calculate(int value) {      /* external function definition */
    return adjust(value) + shared_total;
}

int main(void) {
    printf("result=%d total=%d\n", calculate(1), shared_total);
    return 0;
}

