#ifndef CODESAATHI_API_H
#define CODESAATHI_API_H

extern int shared_total;
int add_to_total(int amount);

#endif

/* api.c */
#include "api.h"

int shared_total = 10;

int add_to_total(int amount) {
    shared_total += amount;
    return shared_total;
}

/* main.c */
#include <stdio.h>
#include "api.h"

int main(void) {
    printf("total=%d\n", add_to_total(5));
    return 0;
}
